merges 0, spawns 0, events 0.
lastSeen now.

Load normalize:
```js
function loadState(){
 let raw; try{raw=localStorage.getItem(SAVE_KEY)}catch{return null}
 if(!raw) return null;
 try{
  const s=JSON.parse(raw);
  if(!s || s.version!==1) return null;
  const base=defaultState();
  const board=Array(CELLS).fill(null);
  (Array.isArray(s.board)?s.board:[]).slice(0,CELLS).forEach((it,i)=>{
    if(it && CHAINS[it.chain] && Number.isInteger(it.level) && it.level>=1 && it.level<=18) board[i]={chain:it.chain,level:it.level};
  });
  const next={...base,...s,board};
  next.highest={...base.highest,...(s.highest||{})};
  next.toppled={...base.toppled,...(s.toppled||{})};
  next.facts={...base.facts,...(s.facts||{})};
  next.buffs={...base.buffs,...(s.buffs||{})};
  for(const id of CHAIN_ORDER){
    next.highest[id]=clamp(Number(next.highest[id])||1,1,18);
    next.toppled[id]=!!next.toppled[id];
    next.facts[id]=Array.isArray(next.facts[id])?next.facts[id].filter(n=>Number.isFinite(n)):[];
  }
  next.ink=clamp(Number(next.ink)||0,0,INK_MAX);
  next.score=Math.max(0,Number(next.score)||0);
  next.nextEvent=Number.isFinite(next.nextEvent)?next.nextEvent:60;
  const elapsed=Math.max(0,Math.min(6*3600,(Date.now()-(Number(s.lastSeen)||Date.now()))/1000));
  if(elapsed>5 && next.started){
    const gain=Math.floor(elapsed*INK_REGEN*0.35);
    const before=next.ink;
    next.ink=Math.min(INK_MAX,next.ink+gain);
    offlineGain=Math.max(0,Math.floor(next.ink-before));
  }
  if(next.nextEvent<=0) next.nextEvent=45;
  next.lastSeen=Date.now();
  return next;
 } catch { return null; }
}
```
- `offlineGain` declared with let before function call? Top-level state loaded after declarations? In JS, `let offlineGain=0` must be declared before `loadState` is called. We'll declare globals then `initState` call at very end? Actually game.js top-level order:
```js
let state=null,...;
...
function loadState...
...
state = loadState() || defaultState();
```
Put assignment after all declarations. Fine. But ui.js needs state defined when it runs; it runs after game.js, so yes.

- `facts` may have levels not valid; filter to f.level. Fine.

Save:
```js
function saveNow(){ try{localStorage.setItem(SAVE_KEY,JSON.stringify({...state,lastSeen:Date.now()}))}catch{} }
function scheduleSave(){ clearTimeout(saveTimer); saveTimer=setTimeout(saveNow,300); }
```

Add helpers:
```js
function clamp(n,min,max){return Math.min(max,Math.max(min,n));}
function fmt(n){return Math.round(n).toLocaleString('en-US');}
function formatTime(sec){...}
function buffActive(k){return (state.buffs[k]||0)>Date.now();}
function toppledCount(){...}
function addInk(n){ state.ink=clamp(state.ink+n,0,INK_MAX); renderHUD(); updateGenerators(); scheduleSave(); }
function addScore(n){ state.score+=n; renderHUD(); scheduleSave(); }
function grantBuff(key, seconds){ state.buffs[key]=Math.max(state.buffs[key]||0,Date.now()+seconds*1000); renderBuffs(); updateGenerators(); scheduleSave(); }
```
- `renderHUD` and `updateGenerators` defined in ui.js; hoisted at call time. addInk called from event after init; fine.
- `renderBuffs` too.
- addInk used in load? no.

`revealFact`:
```js
function revealFact(){
 const candidates=[];
 for(const id of CHAIN_ORDER){
   if(state.toppled[id]) continue;
   const chain=CHAINS[id];
   const f=chain.facts.find(f=>!state.facts[id].includes(f.level));
   if(f) candidates.push({id,f,progress:state.highest[id]});
 }
 if(!candidates.length){ addScore(1000); return false; }
 candidates.sort((a,b)=>b.progress-a.progress);
 const pick=candidates[0];
 state.facts[pick.id].push(pick.f.level);
 renderChains(); renderDetail(); scheduleSave();
 toast(`DECLASSIFIED · ${CHAINS[pick.id].short} — ${pick.f.title}`, 'fact');
 return true;
}
```
- renderChains/detail defined in ui.

`spawnFree`:
```js
function spawnFree(count, offset){
 let placed=0;
 for(const id of CHAIN_ORDER){
  if(state.toppled[id]) continue;
  for(let k=0;k<count;k++){
   const empties=emptyCells(); if(!empties.length)break;
   const lvl=clamp(state.highest[id]-offset,1,17);
   const idx=empties[Math.floor(Math.random()*empties.length)];
   state.board[idx]={chain:id,level:lvl};
   placed++;
  }
 }
 if(placed){ playSound('spawn'); renderAll(); scheduleSave(); }
 return placed;
}
```
- If toppled chain, skip.
- `count` per chain. If event says every dossier, 3 total.
- `offset` 1.

`emptyCells`, `hasEmpty`.

`spawnLevelFor(id)`:
```js
let lvl=clamp(state.highest[id]-1,1,17);
if(buffActive('boostUntil')) lvl=clamp(lvl+1,1,17);
return lvl;
```
- If highest 18, spawn 17, good.
- If highest 2, spawn 1.
- If highest 1, spawn 1.

`spawnCost(id)`:
```js
if(buffActive('freeSpawnUntil')) return 0;
return 4+Math.ceil(spawnLevelFor(id)*1.5);
```

`spawn`:
```js
function spawn(id, {silent=false}={}){
 if(!state.started || state.toppled[id]) return false;
 const lvl=spawnLevelFor(id); const cost=spawnCost(id);
 if(cost>0 && state.ink<cost){ if(!silent){toast('Not enough ink. Merge fragments or wait for the archive to refill.','bad'); playSound('error');} return false; }
 const empties=emptyCells();
 if(!empties.length){ if(!silent){toast('The table is full. Merge matching fragments first.','bad'); playSound('error');} return false; }
 state.ink=Math.max(0,state.ink-cost);
 const idx=empties[Math.floor(Math.random()*empties.length)];
 state.board[idx]={chain:id,level:lvl};
 state.spawns++;
 state.score+=15;
 if(!silent) playSound('spawn');
 renderBoard(); renderHUD(); renderDetail(); updateGenerators(); scheduleSave();
 addFloat(idx,'+15');
 return true;
}
```
- addFloat uses DOM in ui.
- Voluntarily spawn every 220ms; rendering board/detail each time maybe okay.
- `selected` might remain.

`canMerge(a,b)`.

`checkFacts` as before, but toast inside. Return array.

`mergeTiles`:
```js
function mergeTiles(from,to,auto=false){
 const a=state.board[from], b=state.board[to];
 if(!canMerge(a,b)) return {merged:false,toppled:false};
 const chainId=a.chain, level=a.level;
 state.board[from]=null; state.board[to]=null;
 if(selected===from||selected===to) selected=null;
 if(level>=18){
   topple(chainId,to,auto);
   return {merged:true,toppled:true};
 }
 state.board[to]={chain:chainId,level:level+1};
 state.merges++;
 const doubled=buffActive('doubleUntil');
 const gain=(level*level*9+50)*(doubled?2:1);
 state.score+=gain;
 state.ink=Math.min(INK_MAX,state.ink+Math.ceil(level*1.3));
 const newLevel=level+1;
 if(newLevel>state.highest[chainId]) state.highest[chainId]=newLevel;
 const unlocked=checkFacts(chainId);
 if(!auto) playSound('merge');
 renderAll();
 addFloat(to,`+${fmt(gain)}`,doubled?'double':'');
 addSparks(to,CHAINS[chainId].color);
 pulseTile(to,'merging');
 if(unlocked.length) renderChains();
 scheduleSave();
 return {merged:true,toppled:false};
}
```
- `addFloat` then `addSparks` after render. Good.
- On doubled, text maybe "+1,234 ×2"? Use `+${fmt(gain)}` plus class double? addFloat third arg class. CSS `.float-text.double{color:#a9d5dc}` maybe. Add later.
- The tile at target after render. `pulseTile`.
- If auto, silent. Maybe auto topple sound still in topple.

`topple`:
```js
function topple(chainId,contactIdx,auto=false){
 const chain=CHAINS[chainId];
 state.toppled[chainId]=true;
 state.highest[chainId]=18;
 state.merges++;
 state.score+=25000;
 state.ink=Math.min(INK_MAX,state.ink+160);
 state.facts[chainId]=chain.facts.map(f=>f.level);
 selected=null;
 if(CHAINS ... )
 playSound('topple');
 renderAll();
 addFloat(contactIdx,'DOWNFALL','fall');
 addSparks(contactIdx,'#f08a7b');
 screenFlash();
 scheduleSave();
 modalOpen=true; // pause
 setTimeout(()=>showToppleModal(chainId), 520);
}
```
- `showToppleModal` defined in ui.js.
- `modalOpen=true` before timeout. Tick will pause. Good.
- But if event modal happens to be open, `modalOpen` already true and showToppleModal after 520 will replace it. Could happen only if merging while event modal open; UI blocks merge when modalOpen. autoMerge blocked. So fine.
- `state.won`? set in showTopple modal when all.

`trainSelected`:
```js
function trainSelected(){
 if(selected==null) return;
 const item=state.board[selected]; if(!item) return;
 if(item.level>=18){toast(...);playSound('error');return;}
 const cost=trainCost(item.level);
 if(state.ink<cost){toast(...);playSound('error');return;}
 state.ink-=cost;
 item.level++;
 const chainId=item.chain;
 state.score+=140+item.level*25;
 if(item.level>state.highest[chainId]) state.highest[chainId]=item.level;
 checkFacts(chainId);
 playSound('train');
 renderAll();
 addFloat(selected,`TRAINED · TIER ${item.level}`,'');
 pulseTile(selected,'merge');
 scheduleSave();
}
function trainCost(level){ return 10+Math.round(level*5.5); }
```
- After training to 18, `selected` remains 18; detail shows.
