/* ============================================================
   MERGE & FALL — core game state and merge logic
   ============================================================ */
'use strict';

/* ---------------- globals ---------------- */
let state = null;
let selected = null;
let modalOpen = false;
let interludeOpen = false;
let autoRunning = false;
let offlineGain = 0;
let lastTick = Date.now();
let saveTimer = null;

/* ---------------- helpers ---------------- */
function clamp(n, min, max) { return Math.min(max, Math.max(min, n)); }

function fmt(n) { return Math.round(n).toLocaleString('en-US'); }

function formatTime(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

function buffActive(key) { return (state.buffs[key] || 0) > Date.now(); }

function toppledCount() { return CHAIN_ORDER.filter(id => state.toppled[id]).length; }

function emptyCells() {
  const out = [];
  for (let i = 0; i < CELLS; i++) if (!state.board[i]) out.push(i);
  return out;
}

function hasEmpty() { return state.board.some(item => !item); }

function canMerge(a, b) {
  return !!(a && b && a.chain === b.chain && a.level === b.level && a.level <= 18);
}

function trainCost(level) { return 10 + Math.round(level * 5.5); }

/* ---------------- initial state ---------------- */
function defaultState() {
  const board = Array(CELLS).fill(null);
  const seed = [
    [50, 'hitler', 1], [52, 'hitler', 1], [54, 'hitler', 2],
    [49, 'goebbels', 1], [51, 'goebbels', 1], [53, 'goebbels', 2],
    [46, 'himmler', 1], [47, 'himmler', 1], [48, 'himmler', 2]
  ];
  for (const [index, chain, level] of seed) board[index] = { chain, level };

  return {
    version: 1,
    started: false,
    won: false,
    board,
    ink: 120,
    score: 0,
    highest: { hitler: 2, goebbels: 2, himmler: 2 },
    toppled: { hitler: false, goebbels: false, himmler: false },
    facts: { hitler: [], goebbels: [], himmler: [] },
    merges: 0,
    spawns: 0,
    events: 0,
    nextEvent: 70,
    seenEvents: [],
    sound: true,
    buffs: { freeSpawnUntil: 0, doubleUntil: 0, boostUntil: 0 },
    lastSeen: Date.now()
  };
}

/* ---------------- persistence ---------------- */
function loadState() {
  let raw = null;
  try { raw = localStorage.getItem(SAVE_KEY); } catch { return null; }
  if (!raw) return null;

  try {
    const saved = JSON.parse(raw);
    if (!saved || saved.version !== 1) return null;
    const base = defaultState();
    const board = Array(CELLS).fill(null);
    const source = Array.isArray(saved.board) ? saved.board : [];
    source.slice(0, CELLS).forEach((item, i) => {
      if (item && CHAINS[item.chain] && Number.isInteger(item.level) && item.level >= 1 && item.level <= 18) {
        board[i] = { chain: item.chain, level: item.level };
      }
    });

    const next = { ...base, ...saved, board };
    next.highest = { ...base.highest, ...(saved.highest || {}) };
    next.toppled = { ...base.toppled, ...(saved.toppled || {}) };
    next.facts = { ...base.facts, ...(saved.facts || {}) };
    next.buffs = { ...base.buffs, ...(saved.buffs || {}) };

    for (const id of CHAIN_ORDER) {
      next.highest[id] = clamp(Number(next.highest[id]) || 1, 1, 18);
      next.toppled[id] = !!next.toppled[id];
      const facts = Array.isArray(next.facts[id]) ? next.facts[id] : [];
      next.facts[id] = facts.filter(level => CHAINS[id].facts.some(f => f.level === level));
      if (next.toppled[id]) next.facts[id] = CHAINS[id].facts.map(f => f.level);
    }

    next.ink = clamp(Number(next.ink) || 0, 0, INK_MAX);
    next.score = Math.max(0, Number(next.score) || 0);
    next.nextEvent = Number.isFinite(next.nextEvent) ? next.nextEvent : 60;
    next.seenEvents = Array.isArray(next.seenEvents) ? next.seenEvents : [];
    next.buffs = {
      freeSpawnUntil: Number(next.buffs.freeSpawnUntil) || 0,
      doubleUntil: Number(next.buffs.doubleUntil) || 0,
      boostUntil: Number(next.buffs.boostUntil) || 0
    };

    const elapsed = Math.max(0, Math.min(6 * 3600, (Date.now() - (Number(saved.lastSeen) || Date.now())) / 1000));
    if (elapsed > 5 && next.started) {
      const gain = Math.floor(elapsed * INK_REGEN * 0.35);
      const before = next.ink;
      next.ink = Math.min(INK_MAX, next.ink + gain);
      offlineGain = Math.max(0, Math.floor(next.ink - before));
    }
    if (next.nextEvent <= 0) next.nextEvent = 45;
    next.lastSeen = Date.now();
    return next;
  } catch {
    return null;
  }
}

function saveNow() {
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify({ ...state, lastSeen: Date.now() }));
  } catch { /* storage may be unavailable */ }
}

function scheduleSave() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(saveNow, 320);
}

/* ---------------- small effects used by interlude options ---------------- */
function addInk(amount) {
  state.ink = clamp(state.ink + amount, 0, INK_MAX);
  renderHUD();
  updateGenerators();
  scheduleSave();
}

function addScore(amount) {
  state.score = Math.max(0, state.score + amount);
  renderHUD();
  scheduleSave();
}

function grantBuff(key, seconds) {
  state.buffs[key] = Math.max(state.buffs[key] || 0, Date.now() + seconds * 1000);
  renderBuffs();
  updateGenerators();
  scheduleSave();
}

function revealFact() {
  const candidates = [];
  for (const id of CHAIN_ORDER) {
    if (state.toppled[id]) continue;
    const fact = CHAINS[id].facts.find(f => !state.facts[id].includes(f.level));
    if (fact) candidates.push({ id, fact, progress: state.highest[id] });
  }
  if (!candidates.length) {
    addScore(1000);
    return false;
  }
  candidates.sort((a, b) => b.progress - a.progress);
  const pick = candidates[0];
  state.facts[pick.id].push(pick.fact.level);
  renderChains();
  renderDetail();
  toast(`DECLASSIFIED · ${CHAINS[pick.id].short} — ${pick.fact.title}`, 'fact');
  scheduleSave();
  return true;
}

function spawnFree(count, offset) {
  let placed = 0;
  for (const id of CHAIN_ORDER) {
    if (state.toppled[id]) continue;
    for (let k = 0; k < count; k++) {
      const empties = emptyCells();
      if (!empties.length) break;
      const level = clamp(state.highest[id] - offset, 1, 17);
      const index = empties[Math.floor(Math.random() * empties.length)];
      state.board[index] = { chain: id, level };
      placed++;
    }
  }
  if (placed) {
    playSound('spawn');
    renderAll();
    scheduleSave();
  }
  return placed;
}

/* ---------------- spawning ---------------- */
function spawnLevelFor(chainId) {
  let level = clamp(state.highest[chainId] - 1, 1, 17);
  if (buffActive('boostUntil')) level = clamp(level + 1, 1, 17);
  return level;
}

function spawnCost(chainId) {
  if (buffActive('freeSpawnUntil')) return 0;
  return 4 + Math.ceil(spawnLevelFor(chainId) * 1.5);
}

function spawn(chainId) {
  if (!state.started || state.toppled[chainId]) return false;
  const level = spawnLevelFor(chainId);
  const cost = spawnCost(chainId);

  if (cost > 0 && state.ink < cost) {
    toast('Not enough ink. Merge fragments or let the archive refill.', 'bad');
    playSound('error');
    return false;
  }
  const empties = emptyCells();
  if (!empties.length) {
    toast('The table is full. Merge matching fragments first.', 'bad');
    playSound('error');
    return false;
  }

  state.ink = Math.max(0, state.ink - cost);
  const index = empties[Math.floor(Math.random() * empties.length)];
  state.board[index] = { chain: chainId, level };
  state.spawns++;
  state.score += 15;

  playSound('spawn');
  renderBoard();
  renderHUD();
  renderDetail();
  updateGenerators();
  addFloat(index, '+15');
  scheduleSave();
  return true;
}

/* ---------------- merge chain ---------------- */
function checkFacts(chainId) {
  const unlocked = [];
  for (const fact of CHAINS[chainId].facts) {
    if (fact.level <= state.highest[chainId] && !state.facts[chainId].includes(fact.level)) {
      state.facts[chainId].push(fact.level);
      unlocked.push(fact);
    }
  }
  for (const fact of unlocked) {
    toast(`DECLASSIFIED · ${CHAINS[chainId].short} — ${fact.title}`, 'fact');
  }
  return unlocked;
}

function mergeTiles(from, to, auto = false) {
  const a = state.board[from];
  const b = state.board[to];
  if (!canMerge(a, b)) return { merged: false, toppled: false };

  const chainId = a.chain;
  const level = a.level;
  state.board[from] = null;
  state.board[to] = null;
  if (selected === from || selected === to) selected = null;

  if (level >= 18) {
    topple(chainId, to, auto);
    return { merged: true, toppled: true };
  }

  const newLevel = level + 1;
  state.board[to] = { chain: chainId, level: newLevel };
  state.merges++;

  const doubled = buffActive('doubleUntil');
  const gain = (level * level * 9 + 50) * (doubled ? 2 : 1);
  state.score += gain;
  state.ink = Math.min(INK_MAX, state.ink + Math.ceil(level * 1.3));

  if (newLevel > state.highest[chainId]) state.highest[chainId] = newLevel;
  const unlocked = checkFacts(chainId);

  if (!auto) playSound('merge');
  renderAll();
  addFloat(to, `+${fmt(gain)}`, doubled ? 'double' : '');
  addSparks(to, CHAINS[chainId].color);
  pulseTile(to, 'merging');
  if (unlocked.length) renderChains();
  scheduleSave();
  return { merged: true, toppled: false };
}

function topple(chainId, contactIndex, auto = false) {
  if (state.toppled[chainId]) return;
  const chain = CHAINS[chainId];
  state.toppled[chainId] = true;
  state.highest[chainId] = 18;
  state.merges++;
  state.score += 25000;
  state.ink = Math.min(INK_MAX, state.ink + 160);
  state.facts[chainId] = chain.facts.map(f => f.level);

  // The rest of the regime's fragments crumble into the record.
  let cleared = 0;
  for (let i = 0; i < CELLS; i++) {
    if (state.board[i] && state.board[i].chain === chainId) {
      state.board[i] = null;
      cleared++;
    }
  }
  state.score += cleared * 150;
  selected = null;

  playSound('topple');
  renderAll();
  addFloat(contactIndex, 'DOWNFALL', 'fall');
  addSparks(contactIndex, '#f08a7b', 14);
  screenFlash();
  scheduleSave();

  // Pause the table while the downfall card opens.
  modalOpen = true;
  setTimeout(() => showToppleModal(chainId), 520);
}

function trainSelected() {
  if (selected == null) return;
  const item = state.board[selected];
  if (!item) return;
  if (item.level >= 18) {
    toast('This record is already at Tier 18. Merge two Downfall records to topple it.', 'bad');
    playSound('error');
    return;
  }
  const cost = trainCost(item.level);
  if (state.ink < cost) {
    toast(`Training needs ${cost} ink.`, 'bad');
    playSound('error');
    return;
  }

  state.ink -= cost;
  item.level++;
  state.score += 140 + item.level * 25;
  if (item.level > state.highest[item.chain]) state.highest[item.chain] = item.level;
  const unlocked = checkFacts(item.chain);
  if (unlocked.length) renderChains();

  playSound('train');
  renderAll();
  addFloat(selected, `TRAINED · TIER ${item.level}`, 'double');
  pulseTile(selected, 'merge');
  scheduleSave();
}

function moveSelectedTo(index) {
  if (selected == null || state.board[index]) return false;
  const item = state.board[selected];
  if (!item) return false;
  state.board[index] = item;
  state.board[selected] = null;
  selected = index;
  state.score += 5;
  playSound('move');
  renderAll();
  addFloat(index, 'MOVED');
  scheduleSave();
  return true;
}

/* ---------------- merge-all ---------------- */
function findMergePair() {
  const groups = new Map();
  for (let i = 0; i < CELLS; i++) {
    const item = state.board[i];
    if (!item) continue;
    const key = `${item.chain}:${item.level}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(i);
  }
  let best = null;
  for (const ids of groups.values()) {
    if (ids.length < 2) continue;
    const level = state.board[ids[0]].level;
    if (!best || level > best.level) best = { from: ids[0], to: ids[1], level };
  }
  return best;
}

async function autoMerge() {
  if (autoRunning || modalOpen || !state.started) return;
  autoRunning = true;
  updateMergeAllButton();
  let count = 0;
  let didTopple = false;
  const before = toppledCount();

  while (!modalOpen) {
    const pair = findMergePair();
    if (!pair) break;
    const result = mergeTiles(pair.from, pair.to, true);
    if (!result.merged) break;
    count++;
    if (toppledCount() > before) {
      didTopple = true;
      break;
    }
    await sleep(58);
  }

  autoRunning = false;
  updateMergeAllButton();
  renderAll();
  if (count > 0 && !didTopple) {
    playSound('cascade');
    toast(`MERGE ALL · ${count} merge${count === 1 ? '' : 's'} completed.`, 'good');
  }
  if (count > 0) scheduleSave();
}

function resetGame() {
  state = defaultState();
  state.started = true;
  selected = null;
  autoRunning = false;
  saveNow();
  renderAll();
  toast('A new archive has been opened.', 'good');
  playSound('event');
}

/* ---------------- bootstrap state ---------------- */
state = loadState() || defaultState();

/* ============================================================
   MERGE & FALL — rendering, modals, input, audio, lifecycle
   ============================================================ */
'use strict';

const dom = {
  board: document.getElementById('board'),
  detailBar: document.getElementById('detailBar'),
  buffBar: document.getElementById('buffBar'),
  generators: document.getElementById('generators'),
  genHint: document.getElementById('genHint'),
  chains: document.getElementById('chains'),
  modalLayer: document.getElementById('modalLayer'),
  toastLayer: document.getElementById('toastLayer'),
  intro: document.getElementById('intro'),
  introPortraits: document.getElementById('introPortraits'),
  startBtn: document.getElementById('startBtn'),
  introManualBtn: document.getElementById('introManualBtn'),
  introResetBtn: document.getElementById('introResetBtn'),
  soundBtn: document.getElementById('soundBtn'),
  helpBtn: document.getElementById('helpBtn'),
  mergeAllBtn: document.getElementById('mergeAllBtn'),
  resetBtn: document.getElementById('resetBtn'),
  manualBtn: document.getElementById('manualBtn'),
  eventChip: document.getElementById('eventChip'),
  eventTime: document.getElementById('eventTime'),
  inkValue: document.getElementById('inkValue'),
  inkBar: document.getElementById('inkBar'),
  scoreValue: document.getElementById('scoreValue'),
  toppleValue: document.getElementById('toppleValue')
};

let audioCtx = null;
let dragInfo = null;
let holdTimer = null;
let holdInterval = null;
let holdingChain = null;
let lastBuffSig = '';

/* ---------------- rendering ---------------- */
function renderAll() {
  renderHUD();
  renderBoard();
  renderDetail();
  renderBuffs();
  updateGenerators();
  renderChains();
  updateMergeAllButton();
}

function renderHUD() {
  dom.inkValue.textContent = String(Math.floor(state.ink));
  dom.inkBar.style.width = `${(state.ink / INK_MAX) * 100}%`;
  dom.scoreValue.textContent = fmt(state.score);
  dom.toppleValue.textContent = `${toppledCount()}/3`;
  dom.eventTime.textContent = formatTime(state.nextEvent);
  dom.eventChip.classList.toggle('soon', state.started && !state.won && state.nextEvent <= 10);
  dom.eventChip.title = state.won
    ? 'The archive is sealed.'
    : `Next historical interlude in ${formatTime(state.nextEvent)}`;
}

function tileHTML(item, index, isSelected) {
  const chain = CHAINS[item.chain];
  const level = item.level;
  const selectedClass = isSelected ? ' selected' : '';
  const hi = level >= 10 ? ' hi' : '';
  const max = level >= 18 ? ' max' : '';
  const deg = Math.round((level / 18) * 360);
  return `<div class="tile ${item.chain}${hi}${max}${selectedClass}" data-index="${index}" data-lv="${level}" style="--lvl:${level};--deg:${deg}deg" role="button" tabindex="0" aria-label="${chain.name}, tier ${level}, ${chain.stages[level - 1]}. ${level >= 18 ? 'Endgame record: merge with another Downfall to topple the regime.' : `Merge with another tier ${level} fragment to advance.`}">
    <div class="portrait-ring"><div class="portrait">${portraitSVG(item.chain, level)}</div></div>
    <span class="level-num">${String(level).padStart(2, '0')}</span>
    ${level >= 13 ? '<span class="flair">✦</span>' : ''}
    ${level >= 18 ? '<span class="max-mark">FALL</span>' : ''}
  </div>`;
}

function renderBoard() {
  const sel = selected != null ? state.board[selected] : null;
  let html = '';
  for (let i = 0; i < CELLS; i++) {
    const item = state.board[i];
    let cls = 'cell';
    if (!item) cls += ' empty';
    if (sel) {
      if (item && i !== selected && canMerge(sel, item)) cls += ' valid-target';
      else if (!item) cls += ' valid-move';
    }
    if (i === selected) cls += ' selected-cell';
    html += `<div class="${cls}" data-index="${i}" role="gridcell">${item ? tileHTML(item, i, i === selected) : ''}</div>`;
  }
  dom.board.innerHTML = html;
}

function renderDetail() {
  if (selected == null || !state.board[selected]) {
    selected = null;
    dom.detailBar.innerHTML = `<div class="detail-default">
      <div class="hint-icon" aria-hidden="true">⇄</div>
      <div><b>Select a fragment to inspect it.</b><span>Tap a matching twin to merge · drag to move · hold a reconstruction button to repeat.</span></div>
    </div>`;
    return;
  }

  const item = state.board[selected];
  const chain = CHAINS[item.chain];
  const level = item.level;
  const cost = trainCost(level);
  const canTrain = level < 18;
  const toppled = state.toppled[item.chain];

  dom.detailBar.innerHTML = `<div class="detail-portrait">${portraitSVG(item.chain, level)}</div>
    <div class="detail-copy">
      <div class="detail-kicker" style="color:${chain.color}">${chain.short} DOSSIER · TIER ${level} / 18</div>
      <div class="detail-title">${chain.stages[level - 1]}</div>
      <div class="detail-sub">${level >= 18 ? 'Endgame record — merge two <b>Downfall</b> records to topple the regime.' : `Merge with another <b>Tier ${level}</b> fragment to reach Tier ${level + 1}.`}${toppled ? ' The regime is already toppled.' : ''}</div>
    </div>
    <button class="btn btn-gold train-btn" id="trainBtn" type="button" ${!canTrain || toppled || state.ink < cost ? 'disabled' : ''}>${!canTrain ? 'ENDGAME' : `TRAIN TO ${level + 1} · ${cost} INK`}</button>`;
}

function renderBuffs() {
  const now = Date.now();
  const free = Math.ceil((state.buffs.freeSpawnUntil - now) / 1000);
  const double = Math.ceil((state.buffs.doubleUntil - now) / 1000);
  const boost = Math.ceil((state.buffs.boostUntil - now) / 1000);
  const chips = [];
  if (free > 0) chips.push(`<span class="buff-chip">FREE RECONSTRUCTION <b>${free}s</b></span>`);
  if (double > 0) chips.push(`<span class="buff-chip double">DOUBLE EVIDENCE <b>${double}s</b></span>`);
  if (boost > 0) chips.push(`<span class="buff-chip">+1 TIER RECONSTRUCTION <b>${boost}s</b></span>`);
  dom.buffBar.innerHTML = chips.join('');
  dom.buffBar.hidden = chips.length === 0;

  const sig = chips.join('|');
  if (sig !== lastBuffSig) {
    lastBuffSig = sig;
    updateGenerators();
  }
}

function renderChains() {
  dom.chains.innerHTML = CHAIN_ORDER.map(id => {
    const chain = CHAINS[id];
    const highest = state.highest[id];
    const toppled = state.toppled[id];
    const pips = Array.from({ length: 18 }, (_, i) => {
      const level = i + 1;
      let cls = 'pip';
      if (toppled || level <= highest) cls += ' on';
      else if (level === highest + 1) cls += ' next';
      return `<i class="${cls}"></i>`;
    }).join('');

    return `<button class="chain-card ${id}${toppled ? ' toppled' : ''}" data-chain="${id}" type="button" aria-label="Open dossier for ${chain.name}">
      <span class="chain-avatar">${portraitSVG(id, highest)}</span>
      <span class="chain-body">
        <span class="chain-top"><span class="chain-name">${chain.short}</span><span class="chain-tier">${toppled ? 'TOPPLED' : `${String(highest).padStart(2, '0')} / 18`}</span></span>
        <span class="chain-title">${toppled ? 'REGIME FALLEN' : chain.stages[highest - 1]}</span>
        <span class="pips">${pips}</span>
      </span>
      ${toppled ? '<span class="chain-stamp">TOPPLED</span>' : ''}
    </button>`;
  }).join('');
}

function buildGenerators() {
  dom.generators.innerHTML = CHAIN_ORDER.map(id => `<button class="gen ${id}" data-gen="${id}" type="button">
    <span class="gen-seal" data-seal="${id}"></span>
    <span class="gen-text"><b>RECONSTRUCT</b><span>TIER 1 · 6 INK</span></span>
  </button>`).join('');
}

function updateGenerators() {
  const free = buffActive('freeSpawnUntil');
  const empty = hasEmpty();
  for (const id of CHAIN_ORDER) {
    const btn = dom.generators.querySelector(`[data-gen="${id}"]`);
    if (!btn) continue;
    const toppled = state.toppled[id];
    const level = spawnLevelFor(id);
    const cost = spawnCost(id);
    const highest = state.highest[id];
    const seal = btn.querySelector('.gen-seal');
    if (seal.dataset.sealFor !== `${id}:${highest}`) {
      seal.dataset.sealFor = `${id}:${highest}`;
      seal.innerHTML = portraitSVG(id, highest);
    }
    btn.classList.toggle('toppled', toppled);
    btn.disabled = toppled || !empty || (!free && state.ink < cost);
    btn.querySelector('.gen-text b').textContent = toppled ? 'SEALED' : 'RECONSTRUCT';
    btn.querySelector('.gen-text span').textContent = toppled
      ? 'REGIME TOPPLED'
      : `TIER ${level} · ${cost === 0 ? 'FREE' : `${cost} INK`}`;
    btn.setAttribute('aria-label', toppled
      ? `${CHAINS[id].name} is toppled; reconstruction sealed`
      : `Reconstruct ${CHAINS[id].name} at tier ${level} for ${cost} ink`);
    btn.title = toppled ? 'Regime already toppled' : `Spawn tier ${level} (${cost} ink)`;
  }
  dom.genHint.textContent = empty ? 'tap or hold to repeat' : 'table full — merge first';
}

function updateMergeAllButton() {
  const possible = !!findMergePair();
  dom.mergeAllBtn.disabled = !state.started || modalOpen || autoRunning || !possible;
  dom.mergeAllBtn.textContent = autoRunning ? 'MERGING…' : 'MERGE ALL';
}

/* ---------------- visual feedback ---------------- */
function addFloat(index, text, cls = '') {
  const cell = dom.board.querySelector(`.cell[data-index="${index}"]`);
  if (!cell) return;
  const el = document.createElement('div');
  el.className = `float-text${cls ? ` ${cls}` : ''}`;
  el.textContent = text;
  el.style.left = '50%';
  el.style.top = '42%';
  cell.appendChild(el);
  setTimeout(() => el.remove(), 1000);
}

function addSparks(index, color, count = 9) {
  const cell = dom.board.querySelector(`.cell[data-index="${index}"]`);
  if (!cell) return;
  for (let i = 0; i < count; i++) {
    const angle = (Math.PI * 2 * i) / count + Math.random() * 0.5;
    const dist = 16 + Math.random() * 24;
    const spark = document.createElement('span');
    spark.className = 'spark';
    spark.style.left = '50%';
    spark.style.top = '45%';
    spark.style.background = color;
    spark.style.setProperty('--dx', `${Math.cos(angle) * dist}px`);
    spark.style.setProperty('--dy', `${Math.sin(angle) * dist}px`);
    cell.appendChild(spark);
    setTimeout(() => spark.remove(), 700);
  }
}

function pulseTile(index, cls) {
  const tile = dom.board.querySelector(`.cell[data-index="${index}"] .tile`);
  if (!tile) return;
  tile.classList.add(cls);
  setTimeout(() => tile.classList.remove(cls), 520);
}

function shakeCell(index) {
  const cell = dom.board.querySelector(`.cell[data-index="${index}"]`);
  if (!cell) return;
  cell.classList.add('bad-target');
  setTimeout(() => cell.classList.remove('bad-target'), 340);
