const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');

(async () => {
  process.env.DISPLAY = ':0';
  const browser = await chromium.launch({
    executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',
    headless: false,
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-webgl']
  });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  const page = await context.newPage();
  const errors = [];
  const failed = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('response', r => { if (r.status() >= 400) failed.push(`${r.status()} ${r.url()}`); });

  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(600);
  console.log('title:', await page.title());
  console.log('intro visible:', await page.locator('#intro').isVisible());
  console.log('start label:', await page.locator('#startBtn').innerText());
  console.log('cells:', await page.locator('.cell').count(), 'tiles:', await page.locator('.tile').count());
  await page.screenshot({ path: '/tmp/opencode/intro.png', fullPage: false });

  await page.locator('#startBtn').click();
  await page.waitForTimeout(700);
  console.log('intro hidden after start:', await page.locator('#intro').isHidden());
  console.log('board box:', await page.locator('#board').boundingBox());
  console.log('state:', await page.evaluate(() => ({ started: state.started, ink: state.ink, highest: state.highest, merges: state.merges })));
  await page.screenshot({ path: '/tmp/opencode/game-desktop.png', fullPage: false });

  // Merge the two seeded Tier 1 Hitler fragments.
  const pair = await page.evaluate(() => {
    const map = {};
    for (let i = 0; i < state.board.length; i++) {
      const t = state.board[i];
      if (!t) continue;
      const k = t.chain + ':' + t.level;
      (map[k] ||= []).push(i);
    }
    const found = Object.values(map).find(v => v.length >= 2);
    return found ? [found[0], found[1]] : null;
  });
  console.log('merge pair:', pair);
  if (pair) {
    await page.locator(`.cell[data-index="${pair[0]}"] .tile`).click();
    await page.waitForTimeout(100);
    await page.locator(`.cell[data-index="${pair[1]}"] .tile`).click();
    await page.waitForTimeout(500);
  }
  console.log('after merge:', await page.evaluate(() => ({ merges: state.merges, score: state.score, highest: state.highest, ink: state.ink })));

