  const beforeSpawn = await page.evaluate(() => state.spawns);
  await page.locator('.gen[data-gen="himmler"]').click();
  await page.waitForTimeout(300);
  console.log('spawned:', beforeSpawn, '->', await page.evaluate(() => state.spawns));

  // Select a tile and train.
  const target = await page.evaluate(() => state.board.findIndex(t => t && t.level < 18));
  if (target >= 0) {
    await page.locator(`.cell[data-index="${target}"] .tile`).click();
    await page.waitForTimeout(100);
    console.log('train enabled:', await page.locator('#trainBtn').isEnabled());
    if (await page.locator('#trainBtn').isEnabled()) {
      await page.locator('#trainBtn').click();
      await page.waitForTimeout(300);
      console.log('trained item:', await page.evaluate(i => state.board[i], target));
    }
  }
  await page.screenshot({ path: '/tmp/opencode/game-after-actions.png', fullPage: false });

  // Merge all.
  const beforeAuto = await page.evaluate(() => state.merges);
  await page.locator('#mergeAllBtn').click();
  await page.waitForTimeout(2000);
  console.log('auto merges:', beforeAuto, '->', await page.evaluate(() => state.merges));

  // Trigger an interlude.
  await page.evaluate(() => { state.nextEvent = 0.1; });
  await page.waitForTimeout(800);
  console.log('event modal:', await page.locator('#modalLayer .event-option').count());
  if (await page.locator('#modalLayer .event-option').count()) {
    await page.screenshot({ path: '/tmp/opencode/interlude.png' });
    await page.locator('#modalLayer .event-option').first().click();
    await page.waitForTimeout(400);
    console.log('after event:', await page.evaluate(() => ({ events: state.events, next: state.nextEvent, modalOpen })));
  }

  // Dossier.
  await page.locator('.chain-card[data-chain="goebbels"]').click();
  await page.waitForTimeout(300);
  console.log('dossier stages:', await page.locator('.stage-grid .stage-cell').count(), 'facts:', await page.locator('.fact').count());
  await page.screenshot({ path: '/tmp/opencode/dossier.png' });
  await page.locator('.modal-close').click();
  await page.waitForTimeout(200);

  // Force a topple scenario and verify the modal.
  await page.evaluate(() => {
    state.board = Array(56).fill(null);
    state.board[0] = { chain: 'hitler', level: 18 };
    state.board[1] = { chain: 'hitler', level: 18 };
    state.highest.hitler = 18;
    selected = null;
    renderAll();
  });
  await page.locator('.cell[data-index="0"] .tile').click();
  await page.waitForTimeout(100);
  await page.locator('.cell[data-index="1"] .tile').click();
  await page.waitForTimeout(1100);
  console.log('topple modal:', await page.locator('.topple-modal').count(), 'toppled:', await page.evaluate(() => state.toppled.hitler));
  await page.screenshot({ path: '/tmp/opencode/topple.png' });
  if (await page.locator('[data-a="topple-continue"]').count()) {
    await page.locator('[data-a="topple-continue"]').click();
    await page.waitForTimeout(400);
  }

  // Mobile layout in a new page (fresh context, no save).
  const mobile = await context.newPage();
  await mobile.setViewportSize({ width: 390, height: 844 });
  const mErrors = [];
  mobile.on('pageerror', e => mErrors.push(e.message));
  await mobile.goto('http://localhost:3002', { waitUntil: 'load' });
  await mobile.waitForTimeout(300);
  await mobile.locator('#startBtn').click();
  await mobile.waitForTimeout(700);
  console.log('mobile scroll:', await mobile.evaluate(() => ({ w: document.documentElement.scrollWidth, h: document.documentElement.scrollHeight, innerW: innerWidth, innerH: innerHeight })));
  await mobile.screenshot({ path: '/tmp/opencode/game-mobile.png', fullPage: false });
  // open dossier on mobile
  await mobile.locator('.chain-card[data-chain="himmler"]').click();
  await mobile.waitForTimeout(300);
  await mobile.screenshot({ path: '/tmp/opencode/mobile-dossier.png', fullPage: false });
  await mobile.locator('.modal-close').click();

  console.log('errors:', errors);
  console.log('mobile errors:', mErrors);
  console.log('failed:', failed);
  await browser.close();
})().catch(err => { console.error('TEST FAILED', err); process.exit(1); });

