const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  process.env.DISPLAY = ':0';
  const browser = await chromium.launch({
    executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',
    headless: false,
    args: ['--no-sandbox', '--disable-dev-shm-usage']
  });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(400);
  await page.locator('#startBtn').click();
  await page.waitForTimeout(900);
  console.log('desktop page height:', await page.evaluate(() => ({ scrollH: document.documentElement.scrollHeight, innerH: innerHeight, board: document.querySelector('#board').getBoundingClientRect().toJSON(), gens: document.querySelector('#generators').getBoundingClientRect().toJSON() })));
  console.log('ink/gens:', await page.evaluate(() => ({ ink: state.ink, toppled: state.toppled, highest: state.highest })));
  await page.screenshot({ path: '/tmp/opencode/fresh-desktop.png', fullPage: false });

  // Drag test: drag hitler tier 1 over its twin.
  const dragPair = await page.evaluate(() => {
    const map = {};
    for (let i = 0; i < state.board.length; i++) {
      const t = state.board[i];
      if (!t) continue;
      (map[t.chain + ':' + t.level] ||= []).push(i);
    }
    return Object.values(map).find(v => v.length >= 2) || null;
  });
  console.log('drag pair', dragPair);
  if (dragPair) {
    const a = await page.locator(`.cell[data-index="${dragPair[0]}"] .tile`).boundingBox();
    const b = await page.locator(`.cell[data-index="${dragPair[1]}"] .tile`).boundingBox();
    await page.mouse.move(a.x + a.width / 2, a.y + a.height / 2);
    await page.mouse.down();
    await page.mouse.move(b.x + b.width / 2, b.y + b.height / 2, { steps: 12 });
    await page.mouse.up();
    await page.waitForTimeout(500);
    console.log('after drag:', await page.evaluate(() => ({ merges: state.merges, score: state.score, board: state.board.filter(Boolean).length })));
  }
  await page.screenshot({ path: '/tmp/opencode/fresh-desktop-merge.png', fullPage: false });

  // Mobile fresh.
  const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const mp = await mctx.newPage();
  const mErrors = [];
  mp.on('pageerror', e => mErrors.push(e.message));
  await mp.goto('http://localhost:3002', { waitUntil: 'load' });
  await mp.waitForTimeout(300);
  await mp.locator('#startBtn').click();
  await mp.waitForTimeout(800);
  console.log('mobile metrics:', await mp.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, scrollH: document.documentElement.scrollHeight, innerW: innerWidth, board: document.querySelector('#board').getBoundingClientRect().toJSON(), gens: document.querySelector('#generators').getBoundingClientRect().toJSON(), hud: [...document.querySelectorAll('.hud > *')].map(e => ({ text: e.textContent.trim().slice(0, 20), w: e.getBoundingClientRect().width })) })));
  await mp.screenshot({ path: '/tmp/opencode/fresh-mobile.png', fullPage: false });
  await mp.locator('.chain-card[data-chain="hitler"]').click();
  await mp.waitForTimeout(300);
  await mp.screenshot({ path: '/tmp/opencode/fresh-mobile-dossier.png', fullPage: false });

  console.log('errors', errors, mErrors);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

