    await page.locator('.cell[data-index="1"] .tile').click();
    await page.waitForTimeout(750);
    console.log('topple modal for', id, await page.locator('.topple-modal').count(), 'states:', await page.evaluate(() => state.toppled));
    if (id !== 'himmler') {
      await page.locator('[data-a="topple-continue"]').click();
