      if (!t) continue;
      (groups[t.chain + ':' + t.level] ||= []).push(i);
    }
    return Object.values(groups).find(x => x.length >= 2);
  });
  await mp.locator(`.cell[data-index="${mPair[0]}"] .tile`).click();
  await mp.waitForTimeout(100);
  await mp.locator(`.cell[data-index="${mPair[1]}"] .tile`).click();
  await mp.waitForTimeout(400);
  console.log('mobile merge:', await mp.evaluate(() => ({ merges: state.merges, tiles: state.board.filter(Boolean).length })));
  // train
  const t = await mp.evaluate(() => state.board.findIndex(x => x && x.level < 18));
  await mp.locator(`.cell[data-index="${t}"] .tile`).click();
  await mp.waitForTimeout(120);
  console.log('mobile train button box:', await mp.locator('#trainBtn').boundingBox());
  await mp.screenshot({ path: '/tmp/opencode/mobile-selected.png' });
  // open and close dossier
  await mp.locator('.chain-card[data-chain="goebbels"]').click();
  await mp.waitForTimeout(250);
  await mp.locator('.modal-close').click();
  await mp.waitForTimeout(200);
  console.log('mobile modal hidden:', await mp.locator('#modalLayer').isHidden());

  console.log('errors:', errors, mErrors);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

