const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  process.env.DISPLAY = ':0';
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: false, args: ['--no-sandbox'] });
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(200);
  console.log('fresh start label:', await page.locator('#startBtn').innerText());
  await page.locator('#startBtn').click();
  await page.waitForTimeout(400);
  // spawn and merge
  await page.locator('.gen[data-gen="hitler"]').click();
  await page.waitForTimeout(200);
  const pair = await page.evaluate(() => {
    const groups = {};
    for (let i = 0; i < state.board.length; i++) { const t = state.board[i]; if (!t) continue; (groups[t.chain + ':' + t.level] ||= []).push(i); }
    return Object.values(groups).find(x => x.length >= 2);
  });
  await page.locator(`.cell[data-index="${pair[0]}"] .tile`).click();
  await page.waitForTimeout(80);
  await page.locator(`.cell[data-index="${pair[1]}"] .tile`).click();
  await page.waitForTimeout(500);
  const before = await page.evaluate(() => ({ ink: state.ink, score: state.score, merges: state.merges, highest: state.highest.hitler }));
  console.log('before reload', before);
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(400);
  console.log('after reload start label:', await page.locator('#startBtn').innerText(), 'reset visible:', await page.locator('#introResetBtn').isVisible());
  await page.locator('#startBtn').click();
  await page.waitForTimeout(400);
  console.log('after reload state:', await page.evaluate(() => ({ ink: state.ink, score: state.score, merges: state.merges, highest: state.highest.hitler, started: state.started })));

  // Reset confirm
  await page.locator('#resetBtn').click();
  await page.waitForTimeout(200);
  console.log('confirm modal:', await page.locator('.confirm-modal').count());
  await page.locator('[data-a="ok"]').click();
  await page.waitForTimeout(400);
  console.log('after reset:', await page.evaluate(() => ({ merges: state.merges, highest: state.highest.hitler, started: state.started })));

  // Toggle sound
  await page.locator('#soundBtn').click();
  console.log('sound after toggle:', await page.evaluate(() => state.sound), await page.locator('#soundBtn').innerText());

  // Manual open/close
  await page.locator('#helpBtn').click();
  await page.waitForTimeout(250);
  console.log('manual cards:', await page.locator('.manual-card').count());
  await page.locator('.modal-close').click();
  await page.waitForTimeout(150);

  // Event modal mobile width rendering
  await page.evaluate(() => { state.nextEvent = 0.05; });
  await page.waitForTimeout(500);
  console.log('event option count:', await page.locator('.event-option').count());
  await page.locator('.event-option').nth(1).click();
  await page.waitForTimeout(300);
  console.log('event selected:', await page.evaluate(() => ({ events: state.events, modalOpen })));

  // Intro reset path
  await page.evaluate(() => { localStorage.removeItem('merge-and-fall-v1'); });
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(300);
  await page.locator('#startBtn').click();
  await page.waitForTimeout(300);
  await page.locator('#introResetBtn').click().catch(async () => {
    // intro and reset button are hidden after start so this path is not reachable; just note it.
  });
  console.log('errors:', errors);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

