    const b = g.querySelector('.gen-text b')
    const s = getComputedStyle(g), bs = getComputedStyle(b)
    const px = r.x + r.width - 10, py = r.y + r.height / 2
    const el = document.elementFromPoint(px, py)
    out.push({
      chain: g.dataset.gen,
