      bColor: bs.color, bOpacity: bs.opacity, bFilter: bs.filter, bFont: bs.fontSize + ' ' + bs.fontFamily,
      stack: document.elementsFromPoint(px, py).slice(0, 4).map(e => e.className || e.tagName),
      el: el?.className,
    })
  }
  return out
})
console.log(JSON.stringify(info, null, 2))
await browser.close()
